/* converts a str to an u. short, returns the u. short and sets *err on
 * error and if err!=null
  */
static inline unsigned short str2s(const char* s, unsigned int len,
                                                                        int *err)
{
        unsigned short ret;
        int i;
        unsigned char *limit;
        unsigned char *str;

        /*init*/
        str=(unsigned char*)s;
        ret=i=0;
        limit=str+len;

        for(;str<limit ;str++){
                if ( (*str <= '9' ) && (*str >= '0') ){
                                ret=ret*10+*str-'0';
                                i++;
                                if (i>5) goto error_digits;
                }else{
                                //error unknown char
                                goto error_char;
                }
        }
        if (err) *err=0;
        return ret;

error_digits:
        LM_DBG("too many letters in [%.*s]\n", (int)len, s);
        if (err) *err=1;
        return 0;
error_char:
        LM_DBG("unexpected char %c in %.*s\n", *str, (int)len, s);
        if (err) *err=1;
        return 0;
}


